function seriesTrialCount(s){return Math.min(bulkRows(s,{series:true}).filter(r=>r.pending).length,Math.max(1,Number.isInteger(s.trialCount)?s.trialCount:2));}
function seriesRequestIds(s,mode){const ids=bulkRows(s,{series:true}).filter(r=>r.pending).map(r=>r.id);if(mode==='all'||mode==='rest')return ids;if(mode==='selected')return generationSelection(s);if(mode!=='trial')throw Error('请选择先试或全部生成。');return ids.slice(0,seriesTrialCount(s));}
function seriesEntryPanel(){const rows=canvasResults(),c=currentCharacter(),related=(state.series||[]).filter(s=>!s.parentSeriesId).filter(s=>s.characterIds.includes(c?.id)||rows.some(({j})=>j.id===s.sourceJobId)),candidates=rows.filter(({j})=>!related.some(s=>s.sourceJobId===j.id));return panelHead('同风格系列','选一张成图作为画风基准，扩展更多不同角色。')+`${related.length?`<section><h3>继续已有系列</h3>${related.map(s=>`<div class="series-list-row">${resultImageButton(s.sourceAsset,s.sourceName,'ref-mini')}<strong>${esc(s.sourceName)} · ${s.total} 个角色</strong><span class="space"></span><button data-action="open-series" data-id="${s.id}">继续制作</button></div>`).join('')}</section>`:''}${candidates.length?`<h3>选择画风基准 <span class="small muted">${candidates.length} 张 · 点击图片可放大</span></h3><div class="series-results">${candidates.map(({b,j})=>`<article>${resultImageButton(j.asset,j.name,'series-result-image')}<strong>${esc(j.name)}</strong><p class="small muted">${asset(j.asset).w} × ${asset(j.asset).h}</p><button data-action="new-series" data-batch="${b.id}" data-id="${j.id}">${related.some(s=>s.sourceJobId===j.id)?'查看该系列':'用这张扩展'}</button></article>`).join('')}</div>`:!related.length?'<div class="series-entry-empty"><p>先生成或导入一张满意的成图，再用它统一新角色的画风。</p><button class="primary" data-action="batch">前往生成</button></div>':''}<div class="panel-footer"><span class="small muted">只制作当前角色？可直接进入审核。</span><button data-action="review">审核当前结果 ${icon('arrow')}</button></div>`;}
