function restoreSeries(s,raw){s.series=(Array.isArray(raw.series)?raw.series:[]).slice(0,50).filter(x=>x&&/^[\w-]{1,100}$/.test(x.id)).map(x=>({id:x.id,parentSeriesId:cleanText(x.parentSeriesId,100),selectedCharacterIds:Array.isArray(x.selectedCharacterIds)?[...new Set(x.selectedCharacterIds)].filter(id=>(x.characterIds||[]).includes(id)&&s.characters?.some(c=>c.id===id)):null,canvasPosition:restoreCanvasPosition(x.canvasPosition),memberPositions:Object.fromEntries(Object.entries(x.memberPositions||{}).filter(([id,p])=>s.characters?.some(c=>c.id===id)&&restoreCanvasPosition(p)).map(([id,p])=>[id,restoreCanvasPosition(p)])),sourceJobId:cleanText(x.sourceJobId,100),sourceAsset:cleanText(x.sourceAsset,100),sourceName:cleanText(x.sourceName,180),brief:cleanText(x.brief,3000),names:cleanText(x.names,2000),total:Number.isInteger(x.total)?Math.max(2,Math.min(20,x.total)):10,trialCount:Number.isInteger(x.trialCount)?Math.max(1,Math.min(19,x.trialCount)):2,style:cleanText(x.style,2000),styleRules:cleanText(x.styleRules,1000),reviews:restoreSeriesReviews(x.reviews),type:TYPES[x.type]?x.type:'portrait',w:Number(x.w)||0,h:Number(x.h)||0,options:normalizeOptions(x.options),flow:flow({flow:x.flow}),viewHead:x.viewHead!==false,roles:(Array.isArray(x.roles)?x.roles:[]).slice(0,19).map(seriesRow),characterIds:(x.characterIds||[]).filter(id=>s.characters?.some(c=>c.id===id)),batchIds:Object.fromEntries(Object.entries(x.batchIds||{}).filter(([id,b])=>s.characters?.some(c=>c.id===id)&&s.batches.some(x=>x.id===b))),approvedTrials:cleanText(x.approvedTrials,1000),styleRefId:cleanText(x.styleRefId,100),created:cleanText(x.created,100)}));return s;}
