document.addEventListener('input',e=>{const t=e.target,s=seriesById(t.dataset.series);if(!s||s.characterIds.length)return;if(t.dataset.seriesField==='total'){if(!t.value||!t.checkValidity())return;s.total=Number(t.value)+(s.parentSeriesId?1:0);scheduleSave();renderPanel();document.querySelector('[data-series-field="total"]')?.focus();return;}if(['brief','names','styleRules'].includes(t.dataset.seriesField))s[t.dataset.seriesField]=t.value;if(t.dataset.seriesRow!==undefined&&['name','feature','proposal',...DESIGN_FIELDS.map(x=>x[0])].includes(t.dataset.seriesKey)){const r=s.roles[Number(t.dataset.seriesRow)];if(r)r[t.dataset.seriesKey]=t.value;}scheduleSave();});
