async function executeBulk(p,ids,mode='pending',{series=false}={}){
  if(generationBusy||characterBulkBusy||!ids.length)return;if(!imageReady){toast('先连接 Seedream 生图接口。');openPanel('settings');return;}
  saveCharacterContext();const original=state.activeCharacterId,wasView=characterView,project=state,rows=bulkRows(p,{series}).filter(r=>ids.includes(r.id)&&(mode==='failed'?r.failed:r.pending));let bad=null;
  // Frozen tasks retain their submitted recipe; only uncreated tasks use live character settings.
  try{for(const r of rows){if(r.jobs.length)continue;enterCharacter(r.id,{saveCurrent:false,open:false});state.type=p.type;const issues=productionIssues();if(selectedRoles().some(r=>pilotPromptRefs(r).length>10))issues.push({text:'参考图超过 10 张，请精简'});if(issues.length){bad={id:r.id,text:issues[0].text};break;}}}finally{if(original)enterCharacter(original,{saveCurrent:false,open:false});else state.activeCharacterId='';characterView=wasView;}
  if(bad){enterCharacter(bad.id);toast(currentCharacter().name+'：'+bad.text);return;}
  if(state.batches.length+rows.filter(r=>!r.jobs.length).length>60)throw Error('批次容量不足，请导出项目后整理。');
  characterBulkBusy=true;characterBulkStop=false;
  try{
    // Create the complete queue before spending: later resume never depends on checkboxes.
    for(const r of rows){if(r.jobs.length)continue;enterCharacter(r.id,{saveCurrent:false,open:false});state.type=p.type;const b=makeBatch();if(!b)throw Error('未能创建 '+r.c.name+' 的任务。');p.batchIds[r.id]=b.id;saveCharacterContext();}
    scheduleSave();
    for(const r of bulkRows(p,{series}).filter(r=>ids.includes(r.id))){if(state!==project||characterBulkStop)break;if(r.complete)continue;const jobs=r.jobs.filter(j=>!j.asset&&(mode==='failed'?j.generation?.status==='failed':!j.generation));if(!jobs.length)continue;enterCharacter(r.id,{saveCurrent:false,open:false});state.type=p.type;state.activeBatch=r.b.id;selected=3;saveCharacterContext();panel=series?{kind:'series',id:p.id}:{kind:'bulk-plan',id:p.id};render();if(mode==='failed')for(const j of jobs)j.generation=null;await runImageJobs(jobs,r.b);if(jobs.some(j=>!j.asset)){if(series)seriesError='本次队列已停止；未生成任务已保留，可继续未完成，或单独重试失败任务。';break;}}
  }finally{characterBulkBusy=false;if(state===project){saveCharacterContext();if(original)enterCharacter(original,{saveCurrent:false,open:false});else state.activeCharacterId='';characterView='overview';panel=series?{kind:'series',id:p.id}:{kind:'bulk-plan',id:p.id};scheduleSave();render();}}
}
async function generateCharacterBulk(type){const p=rememberBulkPlan(type);await executeBulk(p,p.characterIds);}
document.addEventListener('click',async e=>{const btn=e.target.closest('[data-action]'),a=btn?.dataset.action;if(!['bulk-history','open-bulk-plan','run-bulk-plan','bulk-task-detail','series-resume'].includes(a))return;e.stopImmediatePropagation();if(characterBulkBusy||generationBusy||busy){toast('当前任务处理中，请稍后操作。');return;}try{if(a==='bulk-history'){const plans=state.bulkPlans||[];openPanel(plans.length===1?{kind:'bulk-plan',id:plans[0].id}:'bulk-list');return;}if(a==='series-resume'){const s=seriesById(btn.dataset.id);if(s)await generateSeries(s,btn.dataset.mode==='all'?'all':'selected');return;}const p=bulkPlan(btn.dataset.id);if(!p)return;if(a==='open-bulk-plan'){openPanel({kind:'bulk-plan',id:p.id});return;}if(a==='bulk-task-detail'){const r=bulkRows(p).find(r=>r.id===btn.dataset.character);if(r?.b){enterCharacter(r.id,{open:false});state.activeBatch=r.b.id;openPanel('batch',3);}return;}if(a==='run-bulk-plan')await executeBulk(p,btn.dataset.mode==='selected'?generationSelection(p,false):p.characterIds,btn.dataset.mode==='failed'?'failed':'pending');}catch(err){toast(err.message);}},true);
document.addEventListener('change',e=>{const p=bulkPlan(e.target.dataset.bulkType);if(!p||Object.keys(p.batchIds).length||!TYPES[e.target.value])return;p.type=e.target.value;scheduleSave();renderHeader();});

document.addEventListener('click',async e=>{const btn=e.target.closest('[data-action]'),a=btn?.dataset.action;if(a==='stop-generation')characterBulkStop=true;if(!['character-settings','canvas-series','new-character','open-character','character-overview','character-project','character-bulk','generate-character-bulk','separate-direction'].includes(a))return;e.stopImmediatePropagation();try{
  if((busy||characterBulkBusy)&&['character-settings','canvas-series','new-character','open-character','character-overview'].includes(a)){toast(characterBulkBusy?'批量生成中，可完成本张后停止。':'AI 正在整理当前内容，请稍后切换角色。');return;}
  if(a==='character-settings'){resumeCharacter(btn.dataset.id,{settings:true});return;}if(a==='canvas-series'){openCanvasSeries(btn.dataset.id);return;}if(a==='new-character'){canvasSeriesId='';characterQuery='';addCharacter();return;}if(a==='open-character'){resumeCharacter(btn.dataset.id);return;}
  if(a==='character-overview'){saveCharacterContext();canvasSeriesId='';characterQuery='';characterView='overview';panel=null;scheduleSave();render();fitCharacters();return;}
  if(a==='character-project'){saveCharacterContext();openPanel('character-project');return;}if(a==='character-bulk'){const p=rememberBulkPlan(state.characterDefaults?.type||'portrait');openPanel({kind:'bulk-plan',id:p.id});return;}
  if(a==='generate-character-bulk'){await generateCharacterBulk($('#character-bulk-type').value);return;}
  if(a==='separate-direction'){const c=currentCharacter(),r=state.roles.find(r=>r.id===btn.dataset.id);if(!c||!r||c.roleIds.length<2)return;saveCharacterContext();snapshot();c.roleIds=c.roleIds.filter(id=>id!==r.id);c.context.directionIds=(c.context.directionIds||[]).filter(id=>id!==r.id);state.directionIds=state.directionIds.filter(id=>id!==r.id);const next={id:uid(),name:r.name,roleIds:[r.id],step:0,backgroundView:'results',context:{...structuredClone(c.context),directionIds:[r.id]}};state.characters.push(next);r.enabled=true;enterCharacter(next.id,{saveCurrent:false});}
}catch(err){toast(err.message);}},true);
document.addEventListener('input',e=>{if(e.target.hasAttribute('data-character-query')){characterQuery=e.target.value;renderNodes();fitCharacters();}});
document.addEventListener('change',e=>{const t=e.target;if(t.dataset.characterPick){characterPicks=characterPicks.filter(id=>id!==t.dataset.characterPick);if(t.checked)characterPicks.push(t.dataset.characterPick);renderHeader();}if(t.hasAttribute('data-character-default-type')){state.characterDefaults.type=t.value;scheduleSave();}});
